const items = $input.all();

const filtered = items.filter(item => {
  let settings;
  try {
    settings = typeof item.json.notification_settings === 'string'
      ? JSON.parse(item.json.notification_settings)
      : item.json.notification_settings || {};
  } catch (e) {
    return true;
  }

  return settings.focus_mode !== false;
});

if (filtered.length === 0) return [];
return filtered;

const tasks = $input.all().map(i => i.json);
if (tasks.length === 0) return [];

// Score tasks by priority, urgency, and estimated time
const scored = tasks.map(t => ({
  ...t,
  focus_score: (t.priority_score * 3) + t.urgency_score - (t.estimated_minutes > 120 ? 2 : 0)
}));

// Sort and pick top 3
scored.sort((a, b) => b.focus_score - a.focus_score);
const top3 = scored.slice(0, 3);
const userId = $('Loop Over Users').item.json.id;
const totalMinutes = top3.reduce((sum, t) => sum + (t.estimated_minutes || 30), 0);

return [{
  json: {
    user_id: userId,
    focus_tasks: top3.map((t, idx) => ({
      rank:     idx + 1,
      task_id:  t.id,
      title:    t.title,
      priority: t.priority,
      due_date: t.due_date,
      estimated_minutes: t.estimated_minutes || 30,
      category: t.category
    })),
    total_focus_time: totalMinutes,
    task_count: top3.length
  }
}];
